$_MODULE['<{twopayment}prestashop>twopayment_30cfc25036e6139e5fcf561dcc0879eb'] = 'Hvis du velger JA, kaller kassen Two for å forhåndsvise ordregodkjenning før kjøperen sender betalingen, og viser resultatet i betalingsflisen. Hvis du velger NEI, hoppes dette forhåndskallet over - kjøperen går fortsatt gjennom Twos reelle godkjenningskontroll når betalingen sendes.';
